private fun fillExternalPermissions(items: ArrayList<UItem>, permissions: List<ExternalInstallPermission>, warning: CharSequence?) {
    items.add(UItem.asHeader(LocaleController.getString(R.string.InuPluginsPermissions)))
    if (permissions.isEmpty()) {
        items.add(UItem.asShadow(LocaleController.getString(R.string.InuPluginsPermissionsNone)))
        warning?.let { items.add(UItem.asShadow(it)) }
        return
    }
    permissions.forEachIndexed { index, permission ->
        val rowId = EXTERNAL_GRANT_BASE + index
        val last = index == permissions.lastIndex
        val token = desu.inugram.helpers.plugins.PythonEngineBridge.grantDisplayToken(permission.key)
        if (token != null) {
            val row = externalRows.getOrPut(rowId) {
                PythonGrantRow(context)
            } as PythonGrantRow
            row.bind(token, permission.key in selectedExternal, !last)
            items.add(UItem.asCustom(rowId, row))
        } else {
            val row = externalRows.getOrPut(rowId) {
                NotificationsCheckCell(context)
            } as NotificationsCheckCell
            row.setTextAndValueAndCheck(permission.title, permission.info, permission.key in selectedExternal, 0, true, !last)
            items.add(UItem.asCustom(rowId, row))
        }
    }
    warning?.let { items.add(UItem.asShadow(it)) }
    items.add(UItem.asShadow(null))
}

