@SuppressLint("ClickableViewAccessibility")
private fun buildPythonRow(plugin: Plugin, divider: Boolean): UItem {
    val compact = InuConfig.PLUGINS_COMPACT_LIST.value
    var row = rows[plugin.id]
    if (row == null || row.compact != compact) {
        row = PluginRow(context, compact).also { it.hideHandle() }
        rows[plugin.id] = row
    }
    row.bind(
        plugin,
        onOpen = { presentFragment(PluginInfoActivity(plugin)) },
        onUsernameClick = { username -> messagesController.openByUserName(username, this, 0) },
        onMenu = { anchor -> showPythonOptions(plugin, anchor) },
    ) { enabled -> PluginManager.setEnabled(plugin, enabled) }
    row.bindSettings(if (desu.inugram.helpers.plugins.PythonEngineBridge.hasSettings(plugin)) ({ desu.inugram.helpers.plugins.PythonEngineBridge.openSettings(plugin, this) }) else null)
    row.bindActions(onReload = { PluginManager.reload(plugin) }, onRemove = { removePlugin(plugin) })
    row.setDivider(divider)
    val uitem = if (compact) UItem.asCustom(row, PluginRow.HEIGHT_DP) else UItem.asCustom(row)
    uitem.id = ITEM_BASE + (plugin.id.hashCode() and 0xffff)
    uitem.`object` = plugin
    return uitem
}

private fun showPythonOptions(plugin: Plugin, anchor: View) {
    val bridge = desu.inugram.helpers.plugins.PythonEngineBridge
    ItemOptions.makeOptions(this, anchor)
        .addIf(bridge.hasSettings(plugin), R.drawable.msg_settings, LocaleController.getString(R.string.PluginsMenuOpenSettings)) { bridge.openSettings(plugin, this) }
        .add(R.drawable.msg_permissions, LocaleController.getString(R.string.PluginPermissions)) { bridge.openPermissions(plugin, this) }
        .add(R.drawable.msg_pin, LocaleController.getString(if (bridge.isPinned(plugin)) R.string.DialogUnpin else R.string.DialogPin)) { bridge.togglePinned(plugin) }
        .addIf(plugin.enabled, R.drawable.msg_reset, LocaleController.getString(R.string.InuPluginsReload)) { PluginManager.reload(plugin) }
        .add(R.drawable.msg_delete, LocaleController.getString(R.string.InuPluginsRemove), true) { removePlugin(plugin) }
        .show()
}

