private val engineCells = HashMap<Int, org.telegram.ui.Cells.TextCheckCell>()

private fun engineRow(id: Int, title: Int, icon: Int, color: Int, checked: Boolean, toggle: () -> Boolean): UItem {
    val cell = engineCells.getOrPut(id) {
        org.telegram.ui.Cells.TextCheckCell(context).also { view ->
            view.setBackgroundColor(org.telegram.ui.ActionBar.Theme.getColor(org.telegram.ui.ActionBar.Theme.key_windowBackgroundWhite))
            view.setOnClickListener {
                view.isChecked = toggle()
                listView.adapter.update(true)
            }
        }
    }
    cell.setTextAndCheck(LocaleController.getString(title), checked, true)
    cell.setColorfullIcon(color, icon)
    return UItem.asCustom(id, cell)
}

